SELECT u.uuid as uid,u.username,u.nickname,u.gender,u.signature,u.school,u.github,u.blog, u.avatar,u.email,u.title_name,u.title_color,u.rating, (SELECT COUNT(uid) FROM judge WHERE uid=u.uuid AND cid=0) AS total FROM user_info u
u.status = 0
AND u.uuid = #{uid}
AND u.username = #{username}
